extends SceneTree
## Throwaway probe (not part of the repo): can a fighter already in "hurt" be hit again?
## Scans P2 start distance, P2 walking in or standing, wall or mid-stage, and the tick of
## P1's second press. Steps main.step() by hand: this is a feasibility search only.

func _initialize() -> void:
	_run.call_deferred()

func _run() -> void:
	var found := []
	for wall in [false, true]:
		for walk in [0.0, -1.0]:
			for kind in ["punch", "kick"]:
				for d in range(20, 90):
					for gap in range(0, 14):
						var r: Array = await trial(wall, walk, kind, float(d), gap)
						if r[0]:
							found.append([wall, walk, kind, d, gap, r[1], r[2]])
	print("retrigger cases: ", found.size())
	for f in found.slice(0, 20):
		print("  wall=%s walk=%s kind=%s d=%d gap=%d  first-hit frame=%d  stun before 2nd=%d" % f)
	quit()

func trial(wall: bool, walk: float, kind: String, d: float, gap: int) -> Array:
	var main: Node = load("res://game/main.tscn").instantiate()
	root.add_child(main)
	await process_frame
	main.set_physics_process(false)
	main.start_fight_now()
	var p1: Fighter = main.p1
	var p2: Fighter = main.p2
	if wall:
		p2.position.x = Fighter.ARENA_RIGHT
		p1.position.x = Fighter.ARENA_RIGHT - d
	else:
		p2.position.x = p1.position.x + d
	p1.controller = ScriptedController.new([{"frames": 1 + Fighter.ATTACKS[kind]["startup"] + Fighter.ATTACKS[kind]["active"] + Fighter.ATTACKS[kind]["recovery"] + gap, "attack": kind}, {"frames": 40, "attack": kind}])
	p2.controller = ScriptedController.new([{"frames": 200, "move": walk}])
	var hits := []
	var first_frame := [0]
	p1.attack_resolved.connect(func(_f, _k, res, _p):
		if res == "hit":
			hits.append(1)
			if hits.size() == 1:
				first_frame[0] = p1.frame)
	var ok := false
	var stun_before := -1
	for i in 120:
		var was_hurt := p2.state == "hurt"
		var s := p2.stun
		var n := hits.size()
		main.step(1.0 / 60.0)
		if was_hurt and hits.size() > n and p2.state == "hurt":
			ok = true
			stun_before = s
			break
	main.queue_free()
	await process_frame
	return [ok, first_frame[0], stun_before]

